Step 4 — Read and Extract AGBD from HDF5
A single reusable function handles both regions:

extract_gedi_l4a &lt;- function(h5_path, region) {

  h5    &lt;- H5File$new(h5_path, mode = "r")
  beams &lt;- c("BEAM0000", "BEAM0001", "BEAM0010", "BEAM0011",
             "BEAM0101", "BEAM0110", "BEAM1000", "BEAM1011")

  results &lt;- lapply(beams, function(beam) {
    if (!beam %in% names(h5)) return(NULL)
    tryCatch({
      b &lt;- h5[[beam]]
      data.frame(
        lon        = b[["lon_lowestmode"]][],
        lat        = b[["lat_lowestmode"]][],
        agbd       = b[["agbd"]][],
        agbd_lower = b[["agbd_pi_lower"]][],
        agbd_upper = b[["agbd_pi_upper"]][],
        quality    = b[["l4_quality_flag"]][],
        degrade    = b[["degrade_flag"]][],
        beam       = beam
      )
    }, error = function(e) NULL)
  })

  h5$close_all()

  bind_rows(results) |&gt;
    filter(lon &gt;= region$lon_min, lon &lt;= region$lon_max,
           lat &gt;= region$lat_min, lat &lt;= region$lat_max)
}

# Extract for SCBI
scbi_raw &lt;- list.files("data/gedi_scbi", pattern = "\\.h5$", full.names = TRUE) |&gt;
  lapply(extract_gedi_l4a, region = scbi) |&gt; bind_rows()

# Extract for NYC
nyc_raw  &lt;- list.files("data/gedi_nyc",  pattern = "\\.h5$", full.names = TRUE) |&gt;
  lapply(extract_gedi_l4a, region = nyc)  |&gt; bind_rows()

cat("SCBI raw footprints:", nrow(scbi_raw), "\n")
cat("NYC  raw footprints:", nrow(nyc_raw),  "\n")

Step 6 — Spatial Maps

NEON SCBI

pal_forest &lt;- colorNumeric("YlGn", domain = c(0, 400), na.color = "transparent")

leaflet(st_as_sf(scbi_clean, coords = c("lon", "lat"), crs = 4326)) |&gt;
  addProviderTiles("Esri.WorldImagery") |&gt;
  addCircleMarkers(
    radius      = 3,
    color       = ~pal_forest(agbd),
    fillOpacity = 0.85,
    stroke      = FALSE,
    popup       = ~paste0("&lt;b&gt;AGBD:&lt;/b&gt; ", round(agbd, 1), " Mg/ha&lt;br&gt;",
                          "&lt;b&gt;90% PI:&lt;/b&gt; [", round(agbd_lower, 1), ", ",
                                              round(agbd_upper, 1), "]")
  ) |&gt;
  addLegend(pal = pal_forest, values = ~agbd,
            title = "AGBD (Mg/ha)", position = "bottomright") |&gt;
  addControl("&lt;b&gt;NEON SCBI — Temperate Forest&lt;/b&gt;", position = "topright")



